// Run from apps/mobile: dart run lib/i18n/generate.dart
import 'dart:convert';
import 'dart:io';

void main() {
  String quote(String text) =>
      "'${text.replaceAll('\\', '\\\\').replaceAll("'", "\\'").replaceAll(r'$', r'\$').replaceAll('\n', r'\n').replaceAll('\r', r'\r')}'";
  for (final language in ['zh', 'en']) {
    final data =
        jsonDecode(File('lib/i18n/$language.json').readAsStringSync()) as Map;
    final output = StringBuffer(
      '// GENERATED by lib/i18n/generate.dart from lib/i18n/$language.json.\n\nconst Map<String, String> $language = <String, String>{\n',
    );
    for (final entry in data.entries) {
      output.writeln(
        '  ${quote(entry.key as String)}: ${quote(entry.value as String)},',
      );
    }
    output.writeln('};');
    File('lib/i18n/$language.dart').writeAsStringSync('$output');
  }
}
